<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class BoxOfficeSale extends Model{protected $fillable=['uuid','booking_id','event_id','organizer_id','staff_id','location_id','payment_method','currency','ticket_amount','platform_fee','customer_total','organizer_amount','status','pricing_snapshot'];protected $casts=['pricing_snapshot'=>'array'];public function booking(){return $this->belongsTo(\App\Models\Event\Booking::class);}public function logs(){return $this->hasMany(BoxOfficeSaleLog::class,'sale_id');}}